// pages/LoginPage.js
export class LoginPage {
  constructor(page) {
    this.page = page;
    this.email = page.getByLabel('Email');
    this.sifre = page.getByLabel('Şifrə');
    this.girisDuymesi = page.getByRole('button', { name: 'Daxil ol' });
    this.xeta = page.getByRole('alert');
  }

  async ac() {
    await this.page.goto('/giris');
  }

  async daxilOl(email, sifre) {
    await this.email.fill(email);
    await this.sifre.fill(sifre);
    await this.girisDuymesi.click();
  }
}

