const yanlisGirisler = [
  { ad: 'boş email', email: '', sifre: 'Test123!', mesaj: 'Email tələb olunur' },
  { ad: 'səhv format', email: 'aysel', sifre: 'Test123!', mesaj: 'Email düzgün deyil' },
  { ad: 'qısa şifrə', email: 'aysel@mail.az', sifre: '12', mesaj: 'Şifrə ən azı 8 simvol olmalıdır' },
];

for (const { ad, email, sifre, mesaj } of yanlisGirisler) {
  test(`giriş rədd edilir: ${ad}`, async ({ girisSehifesi }) => {
    await girisSehifesi.daxilOl(email, sifre);
    await expect(girisSehifesi.xeta).toHaveText(mesaj);
  });
}

