import { test, expect } from '@playwright/test';

test('məhsul siyahısı qayıdır', async ({ request }) => {
  const cavab = await request.get('/api/products');

  expect(cavab.status()).toBe(200);
  const mehsullar = await cavab.json();
  expect(mehsullar.length).toBeGreaterThan(0);
  expect(mehsullar[0]).toHaveProperty('ad');
});

test('yeni məhsul yaranır', async ({ request }) => {
  const cavab = await request.post('/api/products', {
    data: { ad: 'Siçan', qiymet: 25 },
  });
  expect(cavab.status()).toBe(201);
});

test('sifariş siyahıda görünür', async ({ page, request }) => {
  // hazırlıq: sifarişi API ilə yarat (0.2 saniyə; UI ilə 15 saniyə çəkərdi)
  const cavab = await request.post('/api/orders', { data: { mehsulId: 7, say: 2 } });
  const { id } = await cavab.json();

  // yoxlama: UI onu göstərirmi?
  await page.goto('/sifarisler');
  await expect(page.getByTestId(`sifaris-${id}`)).toBeVisible();
});

test('məhsul yoxdursa boş vəziyyət göstərilir', async ({ page }) => {
  await page.route('**/api/products', (route) => route.fulfill({ json: [] }));

  await page.goto('/mehsullar');
  await expect(page.getByText('Hələ məhsul yoxdur')).toBeVisible();
});

test('server xətasında mesaj göstərilir', async ({ page }) => {
  await page.route('**/api/products', (route) => route.fulfill({ status: 500 }));

  await page.goto('/mehsullar');
  await expect(page.getByRole('alert')).toContainText('Xəta baş verdi');
});
